(async()=>{const out={};for(const [name,rate,offset,connected,hasBuffer]of [['zero',0,0,true,true],['fast',2,0,true,true],['reverse',-1,200,true,true],['unconnected',2,0,false,true],['null',1,0,true,false]]){const c=new OfflineAudioContext(1,16,8000),s=c.createBufferSource(),events=[];if(hasBuffer)s.buffer=c.createBuffer(1,256,8000);s.playbackRate.value=rate;if(connected)s.connect(c.destination);s.onended=()=>events.push('ended');c.oncomplete=()=>events.push('complete');s.start(0,offset/8000);await c.startRendering();events.push('promise');await new Promise(r=>setTimeout(r,20));out[name]=events}return out})()
